-- Correspondance du contrat : valeurs et libellés conservés, conversions contrôlées.
-- Le document typé sert aux contrôles de structure. Le mode round accepte les
-- décimaux source non représentables exactement en FLOAT64 ; l'extraction lit
-- directement le STRING brut pour éviter une sérialisation numérique intermédiaire.
with parsed as (
    select *, safe.parse_json(payload, wide_number_mode => 'round') as doc
    from {{ source('sncf_raw', 'tgv_reliability') }}
), extracted as (
    select *,
        json_value(payload, '$.date') as v_date,
        json_value(payload, '$.service') as v_service,
        json_value(payload, '$.gare_depart') as v_gare_depart,
        json_value(payload, '$.gare_arrivee') as v_gare_arrivee,
        json_value(payload, '$.duree_moyenne') as v_duree_moyenne,
        json_value(payload, '$.nb_train_prevu') as v_nb_train_prevu,
        json_value(payload, '$.nb_annulation') as v_nb_annulation,
        json_value(payload, '$.commentaire_annulation') as v_commentaire_annulation,
        json_value(payload, '$.nb_train_depart_retard') as v_nb_train_depart_retard,
        json_value(payload, '$.retard_moyen_depart') as v_retard_moyen_depart,
        json_value(payload, '$.retard_moyen_tous_trains_depart') as v_retard_moyen_tous_trains_depart,
        json_value(payload, '$.commentaire_retards_depart') as v_commentaire_retards_depart,
        json_value(payload, '$.nb_train_retard_arrivee') as v_nb_train_retard_arrivee,
        json_value(payload, '$.retard_moyen_arrivee') as v_retard_moyen_arrivee,
        json_value(payload, '$.retard_moyen_tous_trains_arrivee') as v_retard_moyen_tous_trains_arrivee,
        json_value(payload, '$.commentaires_retard_arrivee') as v_commentaires_retard_arrivee,
        json_value(payload, '$.nb_train_retard_sup_15') as v_nb_train_retard_sup_15,
        json_value(payload, '$.retard_moyen_trains_retard_sup15') as v_retard_moyen_trains_retard_sup15,
        json_value(payload, '$.nb_train_retard_sup_30') as v_nb_train_retard_sup_30,
        json_value(payload, '$.nb_train_retard_sup_60') as v_nb_train_retard_sup_60,
        json_value(payload, '$.prct_cause_externe') as v_prct_cause_externe,
        json_value(payload, '$.prct_cause_infra') as v_prct_cause_infra,
        json_value(payload, '$.prct_cause_gestion_trafic') as v_prct_cause_gestion_trafic,
        json_value(payload, '$.prct_cause_materiel_roulant') as v_prct_cause_materiel_roulant,
        json_value(payload, '$.prct_cause_gestion_gare') as v_prct_cause_gestion_gare,
        json_value(payload, '$.prct_cause_prise_en_charge_voyageurs') as v_prct_cause_prise_en_charge_voyageurs
    from parsed
)
select
    version_id, row_number, row_sha256, payload as raw_payload,
    doc is null as invalid_json,
    if(regexp_contains(v_date, r'^[0-9]{4}-[0-9]{2}$'), safe.parse_date('%Y-%m-%d', concat(v_date, '-01')), null) as month,
    v_service as service_type,
    v_gare_depart as departure_station,
    v_gare_arrivee as arrival_station,
    safe_cast(v_duree_moyenne as INT64) as scheduled_duration_minutes,
    safe_cast(v_nb_train_prevu as INT64) as scheduled_trains,
    safe_cast(v_nb_annulation as INT64) as cancelled_trains,
    v_commentaire_annulation as cancellation_comment,
    safe_cast(v_nb_train_depart_retard as INT64) as departure_delayed_trains,
    if(is_nan(safe_cast(v_retard_moyen_depart as FLOAT64)) or is_inf(safe_cast(v_retard_moyen_depart as FLOAT64)), null, safe_cast(v_retard_moyen_depart as FLOAT64)) as mean_departure_delay_late_minutes,
    if(is_nan(safe_cast(v_retard_moyen_tous_trains_depart as FLOAT64)) or is_inf(safe_cast(v_retard_moyen_tous_trains_depart as FLOAT64)), null, safe_cast(v_retard_moyen_tous_trains_depart as FLOAT64)) as mean_departure_delay_all_minutes,
    v_commentaire_retards_depart as departure_delay_comment,
    safe_cast(v_nb_train_retard_arrivee as INT64) as arrival_delayed_trains,
    if(is_nan(safe_cast(v_retard_moyen_arrivee as FLOAT64)) or is_inf(safe_cast(v_retard_moyen_arrivee as FLOAT64)), null, safe_cast(v_retard_moyen_arrivee as FLOAT64)) as mean_arrival_delay_late_minutes,
    if(is_nan(safe_cast(v_retard_moyen_tous_trains_arrivee as FLOAT64)) or is_inf(safe_cast(v_retard_moyen_tous_trains_arrivee as FLOAT64)), null, safe_cast(v_retard_moyen_tous_trains_arrivee as FLOAT64)) as mean_arrival_delay_all_minutes,
    v_commentaires_retard_arrivee as arrival_delay_comment,
    safe_cast(v_nb_train_retard_sup_15 as INT64) as arrival_delayed_over_15_trains,
    if(is_nan(safe_cast(v_retard_moyen_trains_retard_sup15 as FLOAT64)) or is_inf(safe_cast(v_retard_moyen_trains_retard_sup15 as FLOAT64)), null, safe_cast(v_retard_moyen_trains_retard_sup15 as FLOAT64)) as mean_arrival_delay_over_15_minutes,
    safe_cast(v_nb_train_retard_sup_30 as INT64) as arrival_delayed_over_30_trains,
    safe_cast(v_nb_train_retard_sup_60 as INT64) as arrival_delayed_over_60_trains,
    if(is_nan(safe_cast(v_prct_cause_externe as FLOAT64)) or is_inf(safe_cast(v_prct_cause_externe as FLOAT64)), null, safe_cast(v_prct_cause_externe as FLOAT64)) as external_cause_pct,
    if(is_nan(safe_cast(v_prct_cause_infra as FLOAT64)) or is_inf(safe_cast(v_prct_cause_infra as FLOAT64)), null, safe_cast(v_prct_cause_infra as FLOAT64)) as infrastructure_cause_pct,
    if(is_nan(safe_cast(v_prct_cause_gestion_trafic as FLOAT64)) or is_inf(safe_cast(v_prct_cause_gestion_trafic as FLOAT64)), null, safe_cast(v_prct_cause_gestion_trafic as FLOAT64)) as traffic_management_cause_pct,
    if(is_nan(safe_cast(v_prct_cause_materiel_roulant as FLOAT64)) or is_inf(safe_cast(v_prct_cause_materiel_roulant as FLOAT64)), null, safe_cast(v_prct_cause_materiel_roulant as FLOAT64)) as rolling_stock_cause_pct,
    if(is_nan(safe_cast(v_prct_cause_gestion_gare as FLOAT64)) or is_inf(safe_cast(v_prct_cause_gestion_gare as FLOAT64)), null, safe_cast(v_prct_cause_gestion_gare as FLOAT64)) as station_management_cause_pct,
    if(is_nan(safe_cast(v_prct_cause_prise_en_charge_voyageurs as FLOAT64)) or is_inf(safe_cast(v_prct_cause_prise_en_charge_voyageurs as FLOAT64)), null, safe_cast(v_prct_cause_prise_en_charge_voyageurs as FLOAT64)) as passenger_handling_cause_pct,
    array(select field from unnest([
        if((json_type(json_query(doc, '$.date')) not in ('null', 'string')) or (v_date is not null and (if(regexp_contains(v_date, r'^[0-9]{4}-[0-9]{2}$'), safe.parse_date('%Y-%m-%d', concat(v_date, '-01')), null)) is null), 'date', null),
        if((json_type(json_query(doc, '$.service')) not in ('null', 'string')) or (v_service is not null and (v_service) is null), 'service', null),
        if((json_type(json_query(doc, '$.gare_depart')) not in ('null', 'string')) or (v_gare_depart is not null and (v_gare_depart) is null), 'gare_depart', null),
        if((json_type(json_query(doc, '$.gare_arrivee')) not in ('null', 'string')) or (v_gare_arrivee is not null and (v_gare_arrivee) is null), 'gare_arrivee', null),
        if((json_type(json_query(doc, '$.duree_moyenne')) not in ('null', 'number')) or (v_duree_moyenne is not null and (safe_cast(v_duree_moyenne as INT64)) is null), 'duree_moyenne', null),
        if((json_type(json_query(doc, '$.nb_train_prevu')) not in ('null', 'number')) or (v_nb_train_prevu is not null and (safe_cast(v_nb_train_prevu as INT64)) is null), 'nb_train_prevu', null),
        if((json_type(json_query(doc, '$.nb_annulation')) not in ('null', 'number')) or (v_nb_annulation is not null and (safe_cast(v_nb_annulation as INT64)) is null), 'nb_annulation', null),
        if((json_type(json_query(doc, '$.commentaire_annulation')) not in ('null', 'string')) or (v_commentaire_annulation is not null and (v_commentaire_annulation) is null), 'commentaire_annulation', null),
        if((json_type(json_query(doc, '$.nb_train_depart_retard')) not in ('null', 'number')) or (v_nb_train_depart_retard is not null and (safe_cast(v_nb_train_depart_retard as INT64)) is null), 'nb_train_depart_retard', null),
        if((json_type(json_query(doc, '$.retard_moyen_depart')) not in ('null', 'number')) or (v_retard_moyen_depart is not null and (if(is_nan(safe_cast(v_retard_moyen_depart as FLOAT64)) or is_inf(safe_cast(v_retard_moyen_depart as FLOAT64)), null, safe_cast(v_retard_moyen_depart as FLOAT64))) is null), 'retard_moyen_depart', null),
        if((json_type(json_query(doc, '$.retard_moyen_tous_trains_depart')) not in ('null', 'number')) or (v_retard_moyen_tous_trains_depart is not null and (if(is_nan(safe_cast(v_retard_moyen_tous_trains_depart as FLOAT64)) or is_inf(safe_cast(v_retard_moyen_tous_trains_depart as FLOAT64)), null, safe_cast(v_retard_moyen_tous_trains_depart as FLOAT64))) is null), 'retard_moyen_tous_trains_depart', null),
        if((json_type(json_query(doc, '$.commentaire_retards_depart')) not in ('null', 'string')) or (v_commentaire_retards_depart is not null and (v_commentaire_retards_depart) is null), 'commentaire_retards_depart', null),
        if((json_type(json_query(doc, '$.nb_train_retard_arrivee')) not in ('null', 'number')) or (v_nb_train_retard_arrivee is not null and (safe_cast(v_nb_train_retard_arrivee as INT64)) is null), 'nb_train_retard_arrivee', null),
        if((json_type(json_query(doc, '$.retard_moyen_arrivee')) not in ('null', 'number')) or (v_retard_moyen_arrivee is not null and (if(is_nan(safe_cast(v_retard_moyen_arrivee as FLOAT64)) or is_inf(safe_cast(v_retard_moyen_arrivee as FLOAT64)), null, safe_cast(v_retard_moyen_arrivee as FLOAT64))) is null), 'retard_moyen_arrivee', null),
        if((json_type(json_query(doc, '$.retard_moyen_tous_trains_arrivee')) not in ('null', 'number')) or (v_retard_moyen_tous_trains_arrivee is not null and (if(is_nan(safe_cast(v_retard_moyen_tous_trains_arrivee as FLOAT64)) or is_inf(safe_cast(v_retard_moyen_tous_trains_arrivee as FLOAT64)), null, safe_cast(v_retard_moyen_tous_trains_arrivee as FLOAT64))) is null), 'retard_moyen_tous_trains_arrivee', null),
        if((json_type(json_query(doc, '$.commentaires_retard_arrivee')) not in ('null', 'string')) or (v_commentaires_retard_arrivee is not null and (v_commentaires_retard_arrivee) is null), 'commentaires_retard_arrivee', null),
        if((json_type(json_query(doc, '$.nb_train_retard_sup_15')) not in ('null', 'number')) or (v_nb_train_retard_sup_15 is not null and (safe_cast(v_nb_train_retard_sup_15 as INT64)) is null), 'nb_train_retard_sup_15', null),
        if((json_type(json_query(doc, '$.retard_moyen_trains_retard_sup15')) not in ('null', 'number')) or (v_retard_moyen_trains_retard_sup15 is not null and (if(is_nan(safe_cast(v_retard_moyen_trains_retard_sup15 as FLOAT64)) or is_inf(safe_cast(v_retard_moyen_trains_retard_sup15 as FLOAT64)), null, safe_cast(v_retard_moyen_trains_retard_sup15 as FLOAT64))) is null), 'retard_moyen_trains_retard_sup15', null),
        if((json_type(json_query(doc, '$.nb_train_retard_sup_30')) not in ('null', 'number')) or (v_nb_train_retard_sup_30 is not null and (safe_cast(v_nb_train_retard_sup_30 as INT64)) is null), 'nb_train_retard_sup_30', null),
        if((json_type(json_query(doc, '$.nb_train_retard_sup_60')) not in ('null', 'number')) or (v_nb_train_retard_sup_60 is not null and (safe_cast(v_nb_train_retard_sup_60 as INT64)) is null), 'nb_train_retard_sup_60', null),
        if((json_type(json_query(doc, '$.prct_cause_externe')) not in ('null', 'number')) or (v_prct_cause_externe is not null and (if(is_nan(safe_cast(v_prct_cause_externe as FLOAT64)) or is_inf(safe_cast(v_prct_cause_externe as FLOAT64)), null, safe_cast(v_prct_cause_externe as FLOAT64))) is null), 'prct_cause_externe', null),
        if((json_type(json_query(doc, '$.prct_cause_infra')) not in ('null', 'number')) or (v_prct_cause_infra is not null and (if(is_nan(safe_cast(v_prct_cause_infra as FLOAT64)) or is_inf(safe_cast(v_prct_cause_infra as FLOAT64)), null, safe_cast(v_prct_cause_infra as FLOAT64))) is null), 'prct_cause_infra', null),
        if((json_type(json_query(doc, '$.prct_cause_gestion_trafic')) not in ('null', 'number')) or (v_prct_cause_gestion_trafic is not null and (if(is_nan(safe_cast(v_prct_cause_gestion_trafic as FLOAT64)) or is_inf(safe_cast(v_prct_cause_gestion_trafic as FLOAT64)), null, safe_cast(v_prct_cause_gestion_trafic as FLOAT64))) is null), 'prct_cause_gestion_trafic', null),
        if((json_type(json_query(doc, '$.prct_cause_materiel_roulant')) not in ('null', 'number')) or (v_prct_cause_materiel_roulant is not null and (if(is_nan(safe_cast(v_prct_cause_materiel_roulant as FLOAT64)) or is_inf(safe_cast(v_prct_cause_materiel_roulant as FLOAT64)), null, safe_cast(v_prct_cause_materiel_roulant as FLOAT64))) is null), 'prct_cause_materiel_roulant', null),
        if((json_type(json_query(doc, '$.prct_cause_gestion_gare')) not in ('null', 'number')) or (v_prct_cause_gestion_gare is not null and (if(is_nan(safe_cast(v_prct_cause_gestion_gare as FLOAT64)) or is_inf(safe_cast(v_prct_cause_gestion_gare as FLOAT64)), null, safe_cast(v_prct_cause_gestion_gare as FLOAT64))) is null), 'prct_cause_gestion_gare', null),
        if((json_type(json_query(doc, '$.prct_cause_prise_en_charge_voyageurs')) not in ('null', 'number')) or (v_prct_cause_prise_en_charge_voyageurs is not null and (if(is_nan(safe_cast(v_prct_cause_prise_en_charge_voyageurs as FLOAT64)) or is_inf(safe_cast(v_prct_cause_prise_en_charge_voyageurs as FLOAT64)), null, safe_cast(v_prct_cause_prise_en_charge_voyageurs as FLOAT64))) is null), 'prct_cause_prise_en_charge_voyageurs', null)
    ]) field where field is not null) as conversion_error_fields,
    array(select field from unnest([
        if(json_query(doc, '$.date') is null, 'date', null),
        if(json_query(doc, '$.service') is null, 'service', null),
        if(json_query(doc, '$.gare_depart') is null, 'gare_depart', null),
        if(json_query(doc, '$.gare_arrivee') is null, 'gare_arrivee', null),
        if(json_query(doc, '$.duree_moyenne') is null, 'duree_moyenne', null),
        if(json_query(doc, '$.nb_train_prevu') is null, 'nb_train_prevu', null),
        if(json_query(doc, '$.nb_annulation') is null, 'nb_annulation', null),
        if(json_query(doc, '$.commentaire_annulation') is null, 'commentaire_annulation', null),
        if(json_query(doc, '$.nb_train_depart_retard') is null, 'nb_train_depart_retard', null),
        if(json_query(doc, '$.retard_moyen_depart') is null, 'retard_moyen_depart', null),
        if(json_query(doc, '$.retard_moyen_tous_trains_depart') is null, 'retard_moyen_tous_trains_depart', null),
        if(json_query(doc, '$.commentaire_retards_depart') is null, 'commentaire_retards_depart', null),
        if(json_query(doc, '$.nb_train_retard_arrivee') is null, 'nb_train_retard_arrivee', null),
        if(json_query(doc, '$.retard_moyen_arrivee') is null, 'retard_moyen_arrivee', null),
        if(json_query(doc, '$.retard_moyen_tous_trains_arrivee') is null, 'retard_moyen_tous_trains_arrivee', null),
        if(json_query(doc, '$.commentaires_retard_arrivee') is null, 'commentaires_retard_arrivee', null),
        if(json_query(doc, '$.nb_train_retard_sup_15') is null, 'nb_train_retard_sup_15', null),
        if(json_query(doc, '$.retard_moyen_trains_retard_sup15') is null, 'retard_moyen_trains_retard_sup15', null),
        if(json_query(doc, '$.nb_train_retard_sup_30') is null, 'nb_train_retard_sup_30', null),
        if(json_query(doc, '$.nb_train_retard_sup_60') is null, 'nb_train_retard_sup_60', null),
        if(json_query(doc, '$.prct_cause_externe') is null, 'prct_cause_externe', null),
        if(json_query(doc, '$.prct_cause_infra') is null, 'prct_cause_infra', null),
        if(json_query(doc, '$.prct_cause_gestion_trafic') is null, 'prct_cause_gestion_trafic', null),
        if(json_query(doc, '$.prct_cause_materiel_roulant') is null, 'prct_cause_materiel_roulant', null),
        if(json_query(doc, '$.prct_cause_gestion_gare') is null, 'prct_cause_gestion_gare', null),
        if(json_query(doc, '$.prct_cause_prise_en_charge_voyageurs') is null, 'prct_cause_prise_en_charge_voyageurs', null)
    ]) field where field is not null) as missing_schema_fields
from extracted
